import openpyxl
for fn in ['Reports-Studies/DSR_Ph3_StormDrain_HGL.xlsx','Cost Estimates/DSR_Ph3_Engineers_Estimate.xlsx']:
    wb = openpyxl.load_workbook(fn)
    print("=====", fn)
    for ws in wb.worksheets:
        hr = [r for r,d in ws.row_dimensions.items() if d.hidden]
        hc = [c for c,d in ws.column_dimensions.items() if d.hidden]
        print(ws.title, "hidden rows", hr, "hidden cols", hc)
        for row in ws.iter_rows():
            for c in row:
                if c.value is not None and c.font is not None and (c.font.strike or (c.font.color is not None and c.font.color.rgb not in (None,'FF000000') and isinstance(c.font.color.rgb,str))):
                    print("  fmt", c.coordinate, "strike" if c.font.strike else "", c.font.color.rgb if c.font.color else None, repr(c.value)[:80])
                if c.comment:
                    print("  COMMENT", c.coordinate, c.comment.text)
